    "Dockerfile": "FROM python:3.12-slim\nWORKDIR /app\n\n# The SDK is a normal pip dependency from PyPI, listed in requirements.txt.\nCOPY requirements.txt ./\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY . .\n\nRUN groupadd -g 1001 novaos && useradd -r -u 1001 -g 1001 -s /bin/false novaos && \\\n    chown -R novaos:novaos /app\n\nUSER novaos\n\n# NovaOS runs agent containers with a read-only root filesystem.\n# Only /tmp is writable (mounted as emptyDir). Use /tmp for any temp files,\n# caches, or runtime data. Do NOT write to /app or other paths at runtime.\nENV TMPDIR=/tmp\nENV SERVER_PORT=8001\nEXPOSE 8001\n\nCMD [\"uvicorn\", \"server:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8001\"]\n",
    "README.md": "# {{agent_name}}\n\nPython NovaOS agent scaffolded by `novaos-cli init --lang python`.\n\n## Quick start\n\n```bash\npip install -r requirements.txt\npython server.py\n```\n\n## `manifest.json`'s `protocol` field\n\n`manifest.json` declares `\"protocol\": \"A2A\"`. Despite the name, this is not a\nwire protocol — it is an adapter selector, and `\"A2A\"` picks the SDK adapter\n(this template's `server.py` is built on `AgentBuilder` / `asgi_endpoint()`,\nwhich speaks A2A). Leave it as `\"A2A\"` unless you are deliberately building a\nREST agent instead.\n\n## SDK dependency\n\nThe Python client SDK (`novaos_client_sdk`, published as the `novaos-agent-sdk`\npackage) is a normal pip dependency from PyPI, listed in `requirements.txt` —\nno monorepo or manual vendoring required. The version range (`{{python_sdk_version_spec}}`) keeps\nthe agent on a 2.x release; tighten it to an exact version if you need\nreproducible installs.\n",
    "requirements-dev.txt": "# Local development and `novaos-cli test` only — not installed in the Docker image.\npytest==9.0.3\npytest-asyncio==1.3.0\n",
    "requirements.txt": "fastapi==0.115.12\nuvicorn==0.34.2\npydantic==2.11.1\n\n# The NovaOS agent SDK, from PyPI. The range keeps a newly scaffolded agent on\n# a tested 2.x release; the CLI raises the lower bound when a newer release\n# should become the default.\n{{python_sdk_package}}{{python_sdk_version_spec}}\n",
    "server.py": "\"\"\"\n{{agent_name}} — NovaOS Agent (Python)\n\nGenerated by `novaos-cli init --lang python --name {{agent_name}}`\n\"\"\"\n\nimport os\n\nfrom fastapi import FastAPI\nfrom novaos_client_sdk import (\n    A2A_JSONRPC_PATH,\n    AgentBuilder,\n    AgentExecutionContext,\n    SkillResult,\n)\n\napp = FastAPI()\nagent = AgentBuilder(name=\"{{agent_name}}\", version=\"{{version}}\")\n\n\n@agent.skill(\"greet\", description=\"Greet a user by name\")\nasync def greet(ctx: AgentExecutionContext, input_text: str) -> SkillResult:\n    \"\"\"\n    Example skill — receives the user's message as a plain string.\n    Replace with your business logic.\n\n    Access platform tools via ctx.tools:\n        # Memory: use MemoryClient from novaos_client_sdk.memory\n        ctx.tools.llm      — DEPRECATED; use LLMClient (novaos_client_sdk.llm)\n        ctx.tools.knowledge — RAG search\n        ctx.tools.agents    — Agent-to-agent calls\n\n    Every ctx.tools.* call made while handling a streaming request publishes\n    its own tool.call / tool.result event to the caller as it happens — no\n    extra code needed here to get that.\n    \"\"\"\n    name = input_text.strip() or \"World\"\n    return SkillResult(\n        output=f\"Hello, {name}! I am {{agent_name}}.\",\n        status=\"COMPLETED\",\n    )\n\n\n# A2A v1.0 JSON-RPC endpoint — serves both `SendMessage` and\n# `SendStreamingMessage` at the spec's root path (`A2A_JSONRPC_PATH`).\n# `asgi_endpoint()` reads the raw request body itself, so a body that isn't\n# valid JSON gets a JSON-RPC -32700 response instead of an unhandled decode\n# exception. The auth-proxy sidecar strips Authorization and injects\n# X-NovaOS-Execution-Token; the SDK reads both automatically. If you make\n# direct HTTP calls outside the SDK, use:\n#     token = request.headers.get(\"x-novaos-execution-token\", \"\")\n#     httpx.post(url, headers={\"Authorization\": f\"Bearer {token}\"})\napp.post(A2A_JSONRPC_PATH)(agent.asgi_endpoint())\n\n\n@app.get(\"/health\")\nasync def health():\n    return {\"status\": \"ok\", \"agent\": \"{{agent_name}}\"}\n\n\nif __name__ == \"__main__\":\n    import uvicorn\n\n    uvicorn.run(app, host=\"0.0.0.0\", port=int(os.environ.get(\"SERVER_PORT\", \"8001\")))\n",
    "test_agent.py": "\"\"\"\nTests for {{agent_name}}\n\nRun with: novaos-cli test (or pytest directly; install requirements-dev.txt first)\nWorks identically in sandbox and staging.\n\"\"\"\n\nimport json\nfrom unittest.mock import MagicMock\n\nimport pytest\nfrom server import agent, greet\n\n\n@pytest.mark.asyncio\nasync def test_greet_returns_message():\n    \"\"\"Test that the greet skill returns a greeting.\"\"\"\n    ctx = MagicMock()\n    ctx.tools = MagicMock()\n\n    result = await greet(ctx, \"Alice\")\n\n    assert result.status == \"COMPLETED\"\n    assert \"Alice\" in result.output\n\n\n@pytest.mark.asyncio\nasync def test_greet_with_empty_name():\n    \"\"\"Test that the greet skill handles empty input.\"\"\"\n    ctx = MagicMock()\n    ctx.tools = MagicMock()\n\n    result = await greet(ctx, \"\")\n\n    assert result.status == \"COMPLETED\"\n    assert \"World\" in result.output\n\n\ndef test_import_binds_no_port():\n    \"\"\"`novaos-cli publish` runs `python -m novaos_client_sdk.agent_card` to read\n    this agent's Agent Card, which imports server.py the same\n    way this test file already does at the top. That only stays safe as long as\n    `uvicorn.run()` stays behind `if __name__ == \"__main__\":` — an unguarded call\n    there would bind a port (or hang) on import instead of just defining objects.\n    A hard-timeout subprocess catches that case as a failure here instead of as a\n    hang in the publish pipeline.\n    \"\"\"\n    import subprocess\n    import sys\n\n    proc = subprocess.run(\n        [sys.executable, \"-c\", \"import server\"],\n        capture_output=True,\n        timeout=10,\n        check=False,\n    )\n    assert proc.returncode == 0, proc.stderr.decode()\n\n\nclass _FakeRequest:\n    \"\"\"Minimal stand-in for the ASGI request `asgi_endpoint()` expects — just\n    an async `.body()` and a `.headers` mapping. Avoids pulling in an HTTP\n    test client (and its `httpx` dependency) just to check the route wiring.\n    \"\"\"\n\n    def __init__(self, raw: bytes, headers: dict | None = None):\n        self._raw = raw\n        self.headers = headers or {}\n\n    async def body(self) -> bytes:\n        return self._raw\n\n\n@pytest.mark.asyncio\nasync def test_malformed_body_answers_json_rpc_parse_error():\n    \"\"\"A body that isn't valid JSON must get a JSON-RPC -32700 response, not\n    an unhandled decode exception — `server.py` wires the A2A route through\n    `agent.asgi_endpoint()` specifically so this holds without extra code\n    here.\"\"\"\n    endpoint = agent.asgi_endpoint()\n\n    response = await endpoint(_FakeRequest(b\"{not json\"))\n\n    body = json.loads(response.body)\n    assert body[\"error\"][\"code\"] == -32700\n    assert body[\"id\"] is None\n\n\ndef test_sandbox_env_detection():\n    \"\"\"Test that NOVAOS_ENV=sandbox is detected correctly.\"\"\"\n    import os\n\n    original = os.environ.get(\"NOVAOS_ENV\")\n    os.environ[\"NOVAOS_ENV\"] = \"sandbox\"\n    assert os.environ.get(\"NOVAOS_ENV\") == \"sandbox\"\n    if original:\n        os.environ[\"NOVAOS_ENV\"] = original\n    else:\n        del os.environ[\"NOVAOS_ENV\"]\n",
